28	static int lan_http_send_all(int fd, const char *data, size_t length)
29	{
30	  while (length > 0)
31	    {
32	      ssize_t sent = send(fd, data, length, 0);
33	      if (sent <= 0)
34	        {
35	          return sent == 0 ? -EPIPE : -errno;
36	        }
37	      data += sent;
38	      length -= sent;
39	    }
40	
41	  return 0;
42	}
