44	static char *lan_http_find_header_end(char *data, size_t length)
45	{
46	  size_t i;
47	
48	  for (i = 3; i < length; i++)
49	    {
50	      if (data[i - 3] == '\r' && data[i - 2] == '\n' &&
51	          data[i - 1] == '\r' && data[i] == '\n')
52	        {
53	          return data + i + 1;
54	        }
55	    }
56	
57	  return NULL;
58	}
