60	static int lan_http_header_value(char *headers, const char *name,
61	                                 char **value)
62	{
63	  char *line = headers;
64	  size_t name_length = strlen(name);
65	
66	  while (*line != '\0')
67	    {
68	      char *end = strstr(line, "\r\n");
69	      if (end == NULL)
70	        {
71	          return -EINVAL;
72	        }
73	      *end = '\0';
74	      if (strncasecmp(line, name, name_length) == 0 &&
75	          line[name_length] == ':')
76	        {
77	          char *cursor = line + name_length + 1;
78	          while (*cursor == ' ' || *cursor == '\t')
79	            {
80	              cursor++;
81	            }
82	          *value = cursor;
83	          return 0;
84	        }
85	      line = end + 2;
86	    }
87	
88	  return -ENOENT;
89	}
