91	int lan_http_read_request(int fd, struct lan_http_request_s *request)
92	{
93	  char buffer[LAN_HTTP_MAX_HEADERS + 1];
94	  char *header_end;
95	  char *line_end;
96	  char *content_length_text;
97	  size_t used = 0;
98	  size_t header_length;
99	  unsigned long content_length = 0;
100	  ssize_t length;
101	
102	  if (request == NULL)
103	    {
104	      return -EINVAL;
105	    }
106	  memset(request, 0, sizeof(*request));
107	
108	  while (used < LAN_HTTP_MAX_HEADERS)
109	    {
110	      length = lan_http_read_some(fd, buffer + used,
111	                                  LAN_HTTP_MAX_HEADERS - used);
112	      if (length <= 0)
113	        {
114	          return length == 0 ? -ECONNRESET : (int)length;
115	        }
116	      used += length;
117	      buffer[used] = '\0';
118	      header_end = lan_http_find_header_end(buffer, used);
119	      if (header_end != NULL)
120	        {
121	          break;
122	        }
123	    }
124	
125	  if (header_end == NULL)
126	    {
127	      return -E2BIG;
128	    }
129	
130	  line_end = strstr(buffer, "\r\n");
131	  if (line_end == NULL)
132	    {
133	      return -EINVAL;
134	    }
135	  *line_end = '\0';
136	  if (sscanf(buffer, "%7s %255s HTTP/1.%*1[01]", request->method,
137	             request->path) != 2)
138	    {
139	      return -EINVAL;
140	    }
141	
142	  header_length = (size_t)(header_end - (line_end + 2));
143	  (void)header_length;
144	  header_end[-2] = '\0';
145	  if (lan_http_header_value(line_end + 2, "Authorization",
146	                            &content_length_text) == 0)
147	    {
148	      strlcpy(request->authorization, content_length_text,
149	              sizeof(request->authorization));
150	    }
151	
152	  content_length_text = NULL;
153	  if (lan_http_header_value(line_end + 2, "Content-Length",
154	                            &content_length_text) == 0)
155	    {
156	      char *end;
157	      errno = 0;
158	      content_length = strtoul(content_length_text, &end, 10);
159	      if (errno != 0 || *end != '\0' || content_length > sizeof(request->body))
160	        {
161	          return -E2BIG;
162	        }
163	    }
164	
165	  if (content_length > 0)
166	    {
167	      size_t already = used - (size_t)(header_end - buffer);
168	      if (already > content_length)
169	        {
170	          return -EINVAL;
171	        }
172	      if (already > 0)
173	        {
174	          memcpy(request->body, header_end, already);
175	        }
176	      request->body_length = already;
177	      while (request->body_length < content_length)
178	        {
179	          length = lan_http_read_some(fd,
180	                                      request->body + request->body_length,
181	                                      content_length - request->body_length);
182	          if (length <= 0)
183	            {
184	              return length == 0 ? -ECONNRESET : (int)length;
185	            }
186	          request->body_length += length;
187	        }
188	    }
189	
190	  return 0;
191	}
