193	int lan_http_send_response(int fd, int status, const char *type,
194	                           const char *body, size_t length)
195	{
196	  char header[256];
197	  int header_length;
198	
199	  header_length = snprintf(header, sizeof(header),
200	                           "HTTP/1.0 %d\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
201	                           status, type == NULL ? "text/plain" : type,
202	                           (unsigned long)length);
203	  if (header_length < 0 || (size_t)header_length >= sizeof(header))
204	    {
205	      return -E2BIG;
206	    }
207	
208	  if (lan_http_send_all(fd, header, header_length) < 0)
209	    {
210	      return -EPIPE;
211	    }
212	  return body == NULL || length == 0 ? 0 : lan_http_send_all(fd, body, length);
213	}
