215	int lan_http_send_file(int fd, const char *path, const char *type)
216	{
217	  char buffer[LAN_HTTP_CHUNK];
218	  struct stat info;
219	  int file;
220	  int ret;
221	  ssize_t length;
222	
223	  if (stat(path, &info) < 0 || !S_ISREG(info.st_mode))
224	    {
225	      return lan_http_send_response(fd, 404, "text/plain", "Not found\n", 10);
226	    }
227	
228	  {
229	    char header[256];
230	    int header_length = snprintf(header, sizeof(header),
231	                                 "HTTP/1.0 200\r\nContent-Type: %s\r\nContent-Length: %lu\r\nConnection: close\r\n\r\n",
232	                                 type == NULL ? "application/octet-stream" : type,
233	                                 (unsigned long)info.st_size);
234	    if (header_length < 0 || (size_t)header_length >= sizeof(header))
235	      {
236	        return -E2BIG;
237	      }
238	    ret = lan_http_send_all(fd, header, header_length);
239	    if (ret < 0)
240	      {
241	        return ret;
242	      }
243	  }
244	
245	  file = open(path, O_RDONLY);
246	  if (file < 0)
247	    {
248	      return -errno;
249	    }
250	  do
251	    {
252	      length = read(file, buffer, sizeof(buffer));
253	      if (length > 0)
254	        {
255	          ret = lan_http_send_all(fd, buffer, length);
256	        }
257	      else
258	        {
259	          ret = length < 0 ? -errno : 0;
260	        }
261	    }
262	  while (ret == 0 && length > 0);
263	
264	  close(file);
265	  return ret;
266	}
