76	static int lan_panel_write_wifi(const char *body, size_t length)
77	{
78	  struct wifi_config_s config;
79	  char temporary[sizeof(LAN_PANEL_WIFI_CONFIG) + 16];
80	  char text[WIFI_CONFIG_FILE_MAX];
81	  int fd;
82	  int ret;
83	  int written;
84	
85	  if (body == NULL || length == 0 || length >= sizeof(text))
86	    {
87	      return -EINVAL;
88	    }
89	
90	  memset(&config, 0, sizeof(config));
91	  if (wifi_config_parse(body, length, &config) < 0)
92	    {
93	      wifi_config_clear(&config);
94	      return -EINVAL;
95	    }
96	
97	  written = snprintf(text, sizeof(text), "SSID=\"%s\"\nPASSWORD=\"%s\"\n",
98	                     config.ssid, config.password);
99	  wifi_config_clear(&config);
100	  if (written < 0 || (size_t)written >= sizeof(text))
101	    {
102	      return -E2BIG;
103	    }
104	
105	  snprintf(temporary, sizeof(temporary), "%s.tmp", LAN_PANEL_WIFI_CONFIG);
106	  fd = open(temporary, O_WRONLY | O_CREAT | O_EXCL, 0600);
107	  if (fd < 0 && errno == EEXIST)
108	    {
109	      unlink(temporary);
110	      fd = open(temporary, O_WRONLY | O_CREAT | O_EXCL, 0600);
111	    }
112	  if (fd < 0)
113	    {
114	      return -errno;
115	    }
116	
117	  ret = write(fd, text, written) == written ? 0 : -EIO;
118	  if (ret == 0 && fsync(fd) < 0)
119	    {
120	      ret = -errno;
121	    }
122	  close(fd);
123	  memset(text, 0, sizeof(text));
124	  if (ret < 0 || rename(temporary, LAN_PANEL_WIFI_CONFIG) < 0)
125	    {
126	      if (ret == 0)
127	        {
128	          ret = -errno;
129	        }
130	      unlink(temporary);
131	      return ret;
132	    }
133	
134	  return 0;
135	}
