137	static bool lan_panel_safe_component(const char *value, size_t length)
138	{
139	  size_t i;
140	
141	  if (value == NULL || length == 0 || length > 32 ||
142	      strstr(value, "..") != NULL)
143	    {
144	      return false;
145	    }
146	
147	  for (i = 0; i < length; i++)
148	    {
149	      if (!((value[i] >= 'a' && value[i] <= 'z') ||
150	            (value[i] >= 'A' && value[i] <= 'Z') ||
151	            (value[i] >= '0' && value[i] <= '9') ||
152	            value[i] == '_' || value[i] == '-'))
153	        {
154	          return false;
155	        }
156	    }
157	  return true;
