static int lan_panel_read_all(const char *path, char *buffer, size_t size,
                              size_t *length)
{
  int fd = open(path, O_RDONLY);
  size_t used = 0;

  if (fd < 0)
    {
      return -errno;
    }

  while (used < size)
    {
      ssize_t chunk = read(fd, buffer + used, size - used);
      if (chunk == 0)
        {
          break;
        }
      if (chunk < 0)
        {
          int ret = errno == EINTR ? 0 : -errno;
          if (ret < 0)
            {
              close(fd);
              return ret;
            }
          continue;
        }
      used += (size_t)chunk;
    }

  close(fd);
  *length = used;
  return 0;
}

