       * Retry briefly instead of reporting 503 to the page.
       */

      for (attempt = 0; attempt < 3; attempt++)
        {
          ret = lan_panel_read_all(LAN_PANEL_STATUS, body, sizeof(body),
                                   &length);
          if (ret == 0 && length > 0)
            {
              break;
            }
          usleep(30000);
        }

      if (ret < 0 || length == 0)
        {
          return lan_http_send_response(fd, 503, "text/plain",
