  if (strncmp(request.path, "/api/v1/kws/", 12) == 0)
    {
      ret = lan_panel_kws_path(request.path, path, sizeof(path), &type);
      if (ret < 0)
        {
          return lan_http_send_response(fd, 404, "text/plain", "Not found\n", 10);
        }
      return lan_http_send_file(fd, path, type);
    }

  return lan_http_send_response(fd, 404, "text/plain", "Not found\n", 10);
